-- Import seluruh report selesai dari messages.html dan messages2.html
-- Total report: 715
-- Telegram ID diisi dari user_progress jika pencocokan nama aman.
-- ID yang tidak tersedia/ambigu disimpan NULL, bukan ditebak.
-- Jalankan satu kali pada database bot_db melalui phpMyAdmin.

CREATE TABLE IF NOT EXISTS `joined_user_reports` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `source_file` VARCHAR(100) NOT NULL,
  `source_message_id` VARCHAR(50) NOT NULL,
  `user_name` VARCHAR(255) NOT NULL,
  `telegram_id` VARCHAR(100) NULL DEFAULT NULL,
  `reported_at` DATETIME NOT NULL,
  `match_status` ENUM('matched_user_progress','ambiguous_name','telegram_id_unavailable') NOT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_joined_report_source` (`source_file`, `source_message_id`),
  KEY `idx_joined_report_telegram_id` (`telegram_id`),
  KEY `idx_joined_report_reported_at` (`reported_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


